import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [amount, setAmount] = useState(500);
  const [loading, setLoading] = useState(false);
  const [totalRaised, setTotalRaised] = useState(0);
  const [error, setError] = useState(null);
  const goal = 50000; // Your bike goal amount
  const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

  const loadScript = (src) => {
    return new Promise((resolve) => {
      // Check if script is already loaded
      if (document.querySelector(`script[src="${src}"]`)) {
        resolve(true);
        return;
      }

      const script = document.createElement('script');
      script.src = src;
      script.onload = () => resolve(true);
      script.onerror = () => {
        console.error('Failed to load script:', src);
        resolve(false);
      };
      document.body.appendChild(script);
    });
  };

  const handlePayment = async () => {
    setLoading(true);
    setError(null);

    try {
      // Load Razorpay script
      const res = await loadScript('https://checkout.razorpay.com/v1/checkout.js');
      if (!res) {
        setError('Razorpay SDK failed to load. Are you online?');
        return;
      }

      // Validate amount
      if (amount < 10) {
        setError('Please enter an amount greater than ₹10');
        return;
      }

      console.log('Creating order for amount:', amount);

      // Create order
      const orderResponse = await axios.post(`${API_URL}/create-order`, {
        amount: amount
      });

      console.log('Order created:', orderResponse.data);

      const { id: order_id, amount: order_amount } = orderResponse.data;

      const options = {
        key: process.env.REACT_APP_RAZORPAY_KEY_ID,
        amount: order_amount.toString(),
        currency: 'INR',
        name: 'GT Bike Fundraiser',
        description: 'Donation for GT Bike',
        order_id: order_id,
        handler: async function (response) {
          try {
            console.log('Payment successful, saving donation details');
            await axios.post(`${API_URL}/save-donation`, {
              amount: amount,
              razorpay_payment_id: response.razorpay_payment_id,
              razorpay_order_id: response.razorpay_order_id
            });
            alert('Payment successful! Thank you for your donation!');
            // Update the total after successful donation
            fetchTotal();
          } catch (error) {
            console.error('Error saving donation:', error);
            alert('Payment successful but failed to save details.');
          }
        },
        prefill: {
          name: 'Donor',
          email: ''
        },
        theme: {
          color: '#3399cc',
        },
        modal: {
          ondismiss: function() {
            console.log('Payment modal closed');
            setLoading(false);
          }
        }
      };

      console.log('Opening Razorpay with options:', {...options, key: '***hidden***'});

      const paymentObject = new window.Razorpay(options);
      paymentObject.open();
    } catch (error) {
      console.error('Payment error:', error);
      setError(error.response?.data?.error || 'Error processing payment. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // Fetch total raised on component mount
  const fetchTotal = async () => {
    try {
      const response = await axios.get(`${API_URL}/get-donations`);
      setTotalRaised(response.data.total_raised || 0);
    } catch (error) {
      console.error('Error fetching total:', error);
      setError('Failed to fetch donation data');
    }
  };

  useEffect(() => {
    fetchTotal();
  }, []);

  return (
    <div className="app">
      <header>
        <h1>Help Me Get My Dream GT Bike</h1>
      </header>

      <main>
        <div className="progress-container">
          <h3>Fundraising Progress</h3>
          <div className="progress-bar">
            <div
              className="progress-fill"
              style={{ width: `${Math.min(Math.round((totalRaised / goal) * 100), 100)}%` }}
            ></div>
          </div>
          <div className="progress-text">
            <span>₹{totalRaised.toLocaleString()} raised</span>
            <span>Goal: ₹{goal.toLocaleString()}</span>
          </div>
          <div className="progress-percentage">
            {Math.round((totalRaised / goal) * 100)}% Complete
          </div>
        </div>

        <div className="donation-form">
          <h2>Enter Amount to Donate</h2>
          <div className="form-group">
            <label htmlFor="amount">Amount (₹)</label>
            <input
              id="amount"
              type="number"
              min="10"
              value={amount}
              onChange={(e) => setAmount(parseInt(e.target.value) || 0)}
              placeholder="Enter amount in ₹"
            />
          </div>

          {error && <div className="error-message">{error}</div>}

          <button 
            onClick={handlePayment} 
            disabled={loading || amount < 10}
            className={loading ? 'loading' : ''}
          >
            {loading ? 'Processing...' : 'Donate Now'}
          </button>
        </div>
      </main>

      <footer>
        <p>Thank you for your support!</p>
      </footer>
    </div>
  );
}

export default App;
